using NUnit.Framework;using UnityEngine;using LighthouseKeepers.Core;using LighthouseKeepers.Interaction;
namespace LighthouseKeepers.Net.Tests {
 public sealed class ToolBeltTests {
  [Test]public void SlotsAreSeparateAtEveryYawAndHeight(){foreach(float height in new[]{1f,1.7f,2.0f})foreach(float yaw in new[]{0f,90f,180f,270f}){var eye=Vector3.up*height;var q=Quaternion.Euler(45,yaw,0);foreach(var a in new[]{ToolBeltSlot.Radio,ToolBeltSlot.Wrench}){var p=ToolBeltPose.Position(a,eye,q);Assert.True(ToolBeltPose.Near(a,p,eye,q));Assert.True(ToolBeltPose.NearHost(a,p,eye,q));Assert.AreEqual(height-.635f,p.y,.001f);var b=a==ToolBeltSlot.Radio?ToolBeltSlot.Wrench:ToolBeltSlot.Radio;Assert.Greater(Vector3.Distance(p,ToolBeltPose.Position(b,eye,q)),.45f);Assert.False(ToolBeltPose.Near(b,p,eye,q));}}Assert.False(ToolBeltPose.ValidSlot(ToolBeltSlot.Flashlight));}
  [Test]public void InvalidCarryPosesAreRejected(){var e=Vector3.up*1.7f;Assert.False(ToolBeltPose.Near((ToolBeltSlot)99,e,e,Quaternion.identity));Assert.False(ToolBeltPose.Near(ToolBeltSlot.Wrench,Vector3.one*30,e,Quaternion.identity));Assert.False(ToolBeltPose.Near(ToolBeltSlot.Wrench,new Vector3(float.NaN,0,0),e,Quaternion.identity));Assert.False(ToolBeltPose.Near(ToolBeltSlot.Wrench,e,e,new Quaternion()));}
  [Test]public void WrenchHangsDownAndHeadPitchDoesNotTiltSlots(){var q=ToolBeltPose.Rotation(ToolBeltSlot.Wrench,Quaternion.Euler(75,0,0));Assert.Less(Vector3.Distance(q*Vector3.forward,Vector3.up),.001f);Assert.AreEqual(ToolBeltPose.Position(ToolBeltSlot.Wrench,Vector3.up*1.7f,Quaternion.identity),ToolBeltPose.Position(ToolBeltSlot.Wrench,Vector3.up*1.7f,Quaternion.Euler(70,0,0)));}
  [Test]public void HostAllowsTorsoYawLagButRejectsNonWaistPositions(){var eye=Vector3.up*1.7f;var oldYaw=Quaternion.identity;var turned=Quaternion.Euler(0,180,0);foreach(var slot in new[]{ToolBeltSlot.Radio,ToolBeltSlot.Wrench}){var p=ToolBeltPose.Position(slot,eye,oldYaw);Assert.True(ToolBeltPose.NearHost(slot,p,eye,turned));Assert.False(ToolBeltPose.NearHost(slot,p+Vector3.right*4,eye,turned));Assert.False(ToolBeltPose.NearHost(slot,eye,eye,turned));}Assert.False(ToolBeltPose.NearHost(ToolBeltSlot.Flashlight,eye+Vector3.down*.6f,eye,turned));}
  [Test]public void CarryPacketSurvivesRoundTripAndClearsOnRelease(){var packet=new FusionGrabAuthority.Packet{carried=true,owner=2,epoch=3,position=Vector3.one,rotation=Quaternion.identity};var copy=JsonUtility.FromJson<FusionGrabAuthority.Packet>(JsonUtility.ToJson(packet));Assert.True(copy.carried);Assert.AreEqual(2,copy.owner);var go=new GameObject();try{var binding=go.AddComponent<FusionGrabBinding>();typeof(FusionGrabBinding).GetProperty("Owner").SetValue(binding,2);binding.ObserveCarried(true);Assert.True(binding.IsCarried);binding.ReleaseOnHost(Vector3.zero,Quaternion.identity,Vector3.zero,Vector3.zero);Assert.False(binding.IsCarried);}finally{Object.DestroyImmediate(go);}}
 }
}
